###############################################################################
## Supplementary calibration tables: repository version
## Variable-response and GR-only models
###############################################################################
##
## PURPOSE
##
## Recreate the supplementary calibration table objects using only the compact
## processed data included in the repository.
##
## REQUIRED INPUT
##
##   data_processed/primary_tables_repo_data.Rdata
##
## This file is generated by:
##
##   Tables_primary_analysis_full.R
##
## No raw calibration or trajectory simulation files are required.
##
## OUTPUTS
##
##   tables/Tables_Asubende_100.Rdata
##   tables/Tables_Asubende_GR_primary.Rdata
##   tables/Tables_Asubende_GR_wider_prevalence.Rdata
##   tables/Tables_Asubende_GR_comparison.Rdata
##
###############################################################################

dir.create(
  "tables",
  showWarnings = FALSE,
  recursive = TRUE
)

input_file <- "data_processed/primary_tables_repo_data.Rdata"

if (!file.exists(input_file)) {
  stop(
    "Required processed file not found: ",
    input_file,
    "\nRun Tables_primary_analysis_full.R in the full analysis environment ",
    "and include the resulting compact file in the repository."
  )
}

load(input_file)

###############################################################################
## 1. Check required objects
###############################################################################

required_objects <- c(
  "ParameterStatsO",
  "SummaryStatsO",
  "GR_ParameterStatsO",
  "GR_SummaryStatsO",
  "GR_y_primary",
  "GR_final_prev_annual_primary",
  "GR_final_prev_biannual",
  "GR_ParameterStats_wider",
  "GR_SummaryStats_wider",
  "GR_y_wider",
  "GR_final_prev_annual_wider",
  "GR_final_prev_biannual_wider"
)

missing_objects <- required_objects[
  !vapply(
    required_objects,
    exists,
    logical(1),
    inherits = FALSE
  )
]

if (length(missing_objects) > 0) {
  stop(
    "The processed table-data file is missing: ",
    paste(missing_objects, collapse = ", ")
  )
}

###############################################################################
## 2. Variable-response primary calibration
###############################################################################

save(
  ParameterStatsO,
  SummaryStatsO,
  file = "tables/Tables_Asubende_100.Rdata"
)

cat("\nVariable-response primary retained parameter summary:\n")
print(ParameterStatsO)

cat("\nVariable-response primary Asubende outcome summary:\n")
print(SummaryStatsO)


###############################################################################
## 3. GR-only primary calibration
###############################################################################

save(
  GR_ParameterStatsO,
  GR_SummaryStatsO,
  GR_y_primary,
  GR_final_prev_annual_primary,
  GR_final_prev_biannual,
  file = "tables/Tables_Asubende_GR_primary.Rdata"
)

cat("\nGR-only primary retained parameter summary:\n")
print(GR_ParameterStatsO)

cat("\nGR-only primary Asubende outcome summary:\n")
print(GR_SummaryStatsO)


###############################################################################
## 4. GR-only wider-prevalence sensitivity analysis
###############################################################################

save(
  GR_ParameterStats_wider,
  GR_SummaryStats_wider,
  GR_y_wider,
  GR_final_prev_annual_wider,
  GR_final_prev_biannual_wider,
  file = "tables/Tables_Asubende_GR_wider_prevalence.Rdata"
)

cat("\nGR-only wider-prevalence retained parameter summary:\n")
print(GR_ParameterStats_wider)

cat("\nGR-only wider-prevalence Asubende outcome summary:\n")
print(GR_SummaryStats_wider)


###############################################################################
## 5. GR-only primary versus wider-prevalence comparison
###############################################################################

GR_parameter_comparison <- rbind(
  Primary = GR_ParameterStatsO["y", ],
  Wider_prevalence = GR_ParameterStats_wider["y", ]
)

GR_annual_comparison <- rbind(
  Primary =
    GR_SummaryStatsO["Final_mf_prevalence_annual", ],
  Wider_prevalence =
    GR_SummaryStats_wider["Final_mf_prevalence_annual", ]
)

GR_biannual_comparison <- rbind(
  Primary =
    GR_SummaryStatsO["Final_mf_prevalence_biannual", ],
  Wider_prevalence =
    GR_SummaryStats_wider["Final_mf_prevalence_biannual", ]
)

save(
  GR_parameter_comparison,
  GR_annual_comparison,
  GR_biannual_comparison,
  file = "tables/Tables_Asubende_GR_comparison.Rdata"
)

cat("\nGR-only primary versus wider-prevalence biannual comparison:\n")
print(GR_biannual_comparison)

message("\nSupplementary calibration table objects recreated successfully.")
